  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Calculate the final booking price after applying the membership discount rule when applicable.
   * Algorithm:
   * 1. If customer is null, customer.membershipPackage is null, bookingTime is null, or any required reward data is missing, return this.price.
   * 2. Check whether the customer's membership package contains the DISCOUNTS award.
   * 3. Check whether the booking is made at least 24 hours before departure time.
   * 4. If both conditions are satisfied, return this.price with a 20 percent discount applied.
   * 5. The returned amount must keep one decimal place.
   * 6. Otherwise return this.price unchanged.
   * Related Features:
   * - price
   * - departureTime
   * - driver
   * Related Classes: Trip, Customer, MembershipPackage, Award
   * Input:
   * - customer: Customer, the customer making the booking.
   * - bookingTime: String, the booking date/time used to evaluate the 24-hour rule.
   * Output:
   * - double
   * - The final trip price.
   * - The value is rounded/formatted to one decimal place.
   * Pre-condition:
   * - This trip has a valid departure time.
   * - customer may be null, but valid discount evaluation requires customer and membership package.
   * - bookingTime is provided in a comparable date/time format.
   * Post-condition:
   * - No state is modified.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || customer.getMembershipPackage() == null || bookingTime == null || getDepartureTime() == null)
    {
      return Math.round(getPrice() * 10.0) / 10.0;
    }

    MembershipPackage membershipPackage = customer.getMembershipPackage();
    boolean hasDiscounts = membershipPackage.getAwards() != null && membershipPackage.getAwards().contains(Award.DISCOUNTS);
    if (!hasDiscounts)
    {
      return Math.round(getPrice() * 10.0) / 10.0;
    }

    try
    {
      java.time.LocalDateTime bookingDateTime = java.time.LocalDateTime.parse(bookingTime);
      java.time.LocalDateTime departureDateTime = java.time.LocalDateTime.parse(getDepartureTime());
      java.time.Duration duration = java.time.Duration.between(bookingDateTime, departureDateTime);
      if (duration.toHours() < 24)
      {
        return Math.round(getPrice() * 10.0) / 10.0;
      }
    }
    catch (Exception e)
    {
      return Math.round(getPrice() * 10.0) / 10.0;
    }

    return Math.round((getPrice() * 0.8) * 10.0) / 10.0;
    
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Calculate the reward points earned by a customer during a given month.
   * Algorithm:
   * 1. If customer is null, customer.membershipPackage is null, currentMonth is null/empty, or the required reward data is missing, return 0.
   * 2. Check whether the customer's membership package contains the POINTS award.
   * 3. If not, return 0.
   * 4. For each booking associated with the customer, count only bookings whose booking date falls inside currentMonth.
   * 5. Add 5 points per booked seat for each counted booking.
   * 6. Return the total points.
   * Related Features:
   * - bookings
   * - numberOfSeats
   * - calculateMonthlyPoints(customer, currentMonth)
   * Related Classes: Trip, Customer, Booking, MembershipPackage, Award
   * Input:
   * - customer: Customer, the customer whose bookings are evaluated.
   * - currentMonth: String, requested month identifier, expected in a recognizable month format such as "YYYY-MM".
   * Output:
   * - int
   * - Total reward points earned in the requested month.
   * Pre-condition:
   * - customer may be null, but valid computation requires a non-null customer and membership package.
   * - currentMonth is provided in a recognizable month format.
   * Post-condition:
   * - No state is modified.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || customer.getMembershipPackage() == null || currentMonth == null || currentMonth.isEmpty())
    {
      return 0;
    }

    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage.getAwards() == null || !membershipPackage.getAwards().contains(Award.POINTS))
    {
      return 0;
    }

    int total = 0;
    for (Booking booking : customer.getBookings())
    {
      if (booking != null && booking.isInMonth(currentMonth))
      {
        total += booking.getNumberOfSeats() * 5;
      }
    }
    return total;
    
  }

