  public boolean bookSeats(final int num)
  {
    if (num <= 0)
    {
      return false;
    }
    if (getNumberOfSeats() < num)
    {
      return false;
    }
    setNumberOfSeats(getNumberOfSeats() - num);
    return true;
    
  }

